ALTER TABLE public.asaas_contracts ADD COLUMN creation_started_at timestamptz;
CREATE OR REPLACE FUNCTION public.asaas_subscription_current(_subscription uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.asaas_contracts WHERE subscription_id=_subscription) OR EXISTS(SELECT 1 FROM public.asaas_contracts WHERE subscription_id=_subscription AND paid_until>(now() AT TIME ZONE 'America/Sao_Paulo')::date) $$;
REVOKE ALL ON FUNCTION public.asaas_subscription_current(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.asaas_subscription_current(uuid) TO authenticated,service_role;
DO $$ DECLARE signature text; definition text; BEGIN FOREACH signature IN ARRAY ARRAY['public.has_module_access(uuid,text)','public.get_user_entitlements(uuid)','public._matchmaking_draw_state(uuid)'] LOOP definition:=pg_get_functiondef(signature::regprocedure); IF position('public.asaas_subscription_current(s.id)' in definition)=0 THEN definition:=replace(definition,'s.status=''active''','s.status=''active'' AND public.asaas_subscription_current(s.id)'); definition:=replace(definition,'s.status = ''active''','s.status = ''active'' AND public.asaas_subscription_current(s.id)'); EXECUTE definition; END IF; END LOOP; END $$;